"""Torch frontend: capture a ``torch.nn.Module`` forward into the operator IR.

This is the "given a model's forward pass" entry: the module's decode-step
forward is symbolically traced with :mod:`torch.fx`, and the traced graph
is lowered node-by-node onto the same §4.1 recording backend the GPT-2 /
Qwen3 frontends use. Capture stays model-agnostic — nothing here knows a
particular architecture.

Contract (§3.3, §4.2):

* The forward must be traceable: control flow may branch only on Python
  constants; branching on tensor values fails loudly at trace time.
* Nodes in the supported subset lower one-to-one onto recorded operators:

  - ``nn.Embedding`` / ``tensor[ids]`` / ``torchlib.embedding`` → embedding
  - ``nn.Linear`` / ``F.linear`` / ``x @ W`` / ``x @ W.T``       → linear
  - ``nn.LayerNorm`` / ``F.layer_norm``                          → layer_norm
  - ``torchlib.rms_norm``                                        → rms_norm
  - ``torchlib.rope``                                            → rope
  - ``torchlib.swiglu``, and the ``silu(g) * u`` pattern         → swiglu
  - ``+`` (same-shape residual)                                  → add
  - ``torch.gelu``                                               → gelu
  - ``torchlib.decode_attention`` (append + QK^T + softmax + PV) →
    cache_append, attention_scores, softmax, attention_values
  - view/reshape/squeeze/transpose/chunk/slice/select            → views

* Anything else is rejected with a §3.3 diagnostic naming the node and the
  missing contract — never silently run as an external kernel.

The same module runs eagerly with real tensors (``torchlib`` helpers are
plain torch functions), which gives an oracle that shares no code with the
compiled schedule: compare ``execute()`` against the eager forward.

This module imports torch lazily; the compiler package itself stays
torch-free at the IR level.
"""

from __future__ import annotations

import operator
from typing import Any, Mapping, Optional, Sequence

from .capture import (
    CaptureError,
    RecordingBackend,
    SymbolicTensor,
    UnsupportedOperator,
)

__all__ = ["torchlib", "capture_torch_forward", "compile_torch_forward"]


# ---------------------------------------------------------------------------
# torchlib: the decode-step helper library
# ---------------------------------------------------------------------------


class _TorchLib:
    """Eager torch implementations of the fused decode-step operators.

    A model's forward calls these helpers (instead of hand-rolled
    ``torch.cat`` RoPE, ``F.scaled_dot_product_attention``, ...). Called
    with real tensors they compute eagerly — the oracle. Called under
    :func:`capture_torch_forward`, the tracer lowers each call to the
    matching recorded operator.
    """

    @staticmethod
    def embedding(ids, table, pos_table=None, p=None):
        out = table[ids.long()]
        if pos_table is not None:
            out = out + pos_table[p]
        return out

    @staticmethod
    def rms_norm(x, gamma, eps=1e-6):
        import torch

        var = x.to(torch.float32).pow(2).mean(-1, keepdim=True)
        return (x * torch.rsqrt(var + eps) * gamma).to(x.dtype)

    @staticmethod
    def rope(x, cos, sin, p):
        half = x.shape[-1] // 2
        rotated = torch.cat((-x[..., half:], x[..., :half]), dim=-1) if False else _TorchLib._rotate_half(x)
        return x * cos[p] + rotated * sin[p]

    @staticmethod
    def _rotate_half(x):
        import torch

        half = x.shape[-1] // 2
        return torch.cat((-x[..., half:], x[..., :half]), dim=-1)

    @staticmethod
    def swiglu(gate, up):
        import torch

        return torch.nn.functional.silu(gate) * up

    @staticmethod
    def decode_attention(q, k_new, v_new, k_cache, v_cache, p, *, layer=0, kv_heads=None, scale=None):
        """Append k/v at position ``p`` and attend over the valid prefix.

        ``k_cache``/``v_cache`` are per-layer views shaped [B, KVH, S, D];
        they are mutated in place at [..., p, :] (eager path) / through the
        recorded cache_append effect (captured path). Returns ctx [B, H, D].
        """
        import math

        import torch

        B, H, D = q.shape
        kvh = kv_heads or H
        group = H // kvh
        scale = scale if scale is not None else 1.0 / math.sqrt(D)

        k_cache[..., p, :] = k_new
        v_cache[..., p, :] = v_new
        K = k_cache[..., : p + 1, :]  # [B, KVH, p+1, D]
        V = v_cache[..., : p + 1, :]

        kvh_of_h = torch.arange(H, device=q.device) // group  # q head -> kv head
        scores = torch.einsum("bhd,bhtd->bht", q.to(torch.float32), K[:, kvh_of_h].to(torch.float32)) * scale
        scores = scores - scores.max(dim=-1, keepdim=True).values
        probs = torch.exp(scores)
        probs = probs / probs.sum(dim=-1, keepdim=True)
        ctx = torch.einsum("bht,bhtd->bhd", probs, V[:, kvh_of_h].to(torch.float32))
        return ctx.to(q.dtype)


torchlib = _TorchLib()


# ---------------------------------------------------------------------------
# FX interpretation -> recording backend
# ---------------------------------------------------------------------------


class _UnsupportedNode(CaptureError):
    def __init__(self, node, why: str):
        super().__init__(f"torch node {node!r} is outside the supported subset: {why}")


def _torch():
    import torch

    return torch


def _fx_trace(module):
    try:
        import torch.fx as fx

        return fx.symbolic_trace(module)
    except Exception as exc:  # Proxy errors on data-dependent control flow etc.
        raise CaptureError(
            f"torch.fx could not trace the module ({type(exc).__name__}: {exc}); "
            "the forward must branch only on Python constants (§4.2)"
        ) from exc


def _attr_of(module, dotted: str):
    obj = module
    for part in dotted.split("."):
        obj = getattr(obj, part)
    return obj


class _GraphLowering:
    """Interprets an fx graph with symbolic values, recording operators."""

    def __init__(
        self,
        ops: RecordingBackend,
        gm,
        module,
        example_inputs: Mapping[str, Any],
        scalars: Mapping[str, tuple[int, int]],
    ):
        self.ops = ops
        self.gm = gm
        self.module = module
        self.example_inputs = dict(example_inputs)
        self.scalar_specs = dict(scalars)
        self.env: dict[Any, Any] = {}
        self.scalars: dict[str, Any] = {}  # placeholder name -> SymbolicScalar
        self._weight_names: set[str] = set()

    # -- registration helpers -------------------------------------------------

    def _external(self, name: str, tensor) -> SymbolicTensor:
        if name in self._weight_names:
            # re-requested attribute: RecordingBackend dedupes by name/shape
            pass
        return self.ops.register_external(name, tensor)

    def _scalar_of(self, value):
        return self.scalars[value] if isinstance(value, str) else value

    # -- node dispatch ---------------------------------------------------------

    def run(self) -> tuple[str, ...]:
        for node in self.gm.graph.nodes:
            if node.op == "placeholder":
                self.env[node] = self._lower_placeholder(node)
            elif node.op == "get_attr":
                self.env[node] = self._lower_get_attr(node)
            elif node.op == "call_function":
                self.env[node] = self._lower_call_function(node)
            elif node.op == "call_method":
                self.env[node] = self._lower_call_method(node)
            elif node.op == "call_module":
                self.env[node] = self._lower_call_module(node)
            elif node.op == "output":
                return self._lower_output(node)
        raise CaptureError("traced graph has no output node")

    def _lower_placeholder(self, node):
        name = str(node.target)
        if name in self.example_inputs:
            return self._external(name, self.example_inputs[name])
        if name in self.scalar_specs:
            lo, hi = self.scalar_specs[name]
            sc = self.ops.define_scalar(name, lo, hi)
            self.scalars[name] = sc
            return sc
        raise CaptureError(
            f"placeholder {name!r} is neither an example input nor a declared scalar; "
            "pass it via example_inputs/scalars so capture can bind it"
        )

    def _lower_get_attr(self, node):
        tensor = _attr_of(self.gm, str(node.target))
        name = str(node.target).replace(".", "_")
        if not hasattr(tensor, "shape"):
            raise _UnsupportedNode(node, f"attribute {node.target!r} is not a tensor (constants must enter as Python literals)")
        self._weight_names.add(name)
        return self._external(name, tensor)

    def _lower_output(self, node):
        val = self.env.get(node.args[0], node.args[0]) if node.args else None
        names = []
        vals = val if isinstance(val, (tuple, list)) else [val]
        for v in vals:
            if not isinstance(v, SymbolicTensor):
                raise _UnsupportedNode(node, f"output {v!r} is not a tensor; the compiled kernel's outputs must be tensor values")
            names.append(v.value.name)
        return tuple(names)

    # -- call_module: recognized parameterized layers ---------------------------

    def _lower_call_module(self, node):
        torch = _torch()
        mod = self._attr_of(self.module, str(node.target))
        args = [self.env.get(a, a) for a in node.args]
        kwargs = {k: self.env.get(v, v) for k, v in node.kwargs.items()}

        if isinstance(mod, torch.nn.Linear):
            x = self._tensor_arg(node, args[0])
            w = self._external(f"{node.name}_weight", mod.weight)  # [out, in]
            wt = self.ops.transpose_view(w, f"{w.value.name}.T")  # [in, out]
            b = self._external(f"{node.name}_bias", mod.bias) if mod.bias is not None else None
            return self.ops.linear(x, wt, b, name=str(node.target).replace(".", "_"))
        if isinstance(mod, torch.nn.LayerNorm):
            x = self._tensor_arg(node, args[0])
            g = self._external(f"{node.name}_weight", mod.weight)
            b = self._external(f"{node.name}_bias", mod.bias) if mod.bias is not None else self._zero_bias(node)
            return self.ops.layer_norm(x, g, b, mod.eps, name=str(node.target).replace(".", "_"))
        if isinstance(mod, torch.nn.Embedding):
            ids = self._tensor_arg(node, args[0])
            w = self._external(f"{node.name}_weight", mod.weight)
            return self.ops.embedding(ids, w, None, self._position())
        raise _UnsupportedNode(node, f"module type {type(mod).__name__} has no megakernel lowering")

    def _zero_bias(self, node):
        import numpy as np

        mod = self._attr_of(self.module, str(node.target))
        return self._external(f"{node.name}_zero_bias", np.zeros(mod.normalized_shape, dtype=np.float32))

    def _position(self):
        # The canonical decode position, if the model declared one.
        return self.scalars.get("p")

    # -- call_function: functional ops + torchlib helpers ------------------------

    def _lower_call_function(self, node):
        torch = _torch()
        target = node.target
        args = [self.env.get(a, a) for a in node.args]
        kwargs = {k: self.env.get(v, v) for k, v in node.kwargs.items()}

        # ---- torchlib fused helpers ----------------------------------------
        if target == torchlib.embedding:
            ids, table = self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1])
            pos_table = self._tensor_arg(node, args[2]) if len(args) > 2 and isinstance(args[2], SymbolicTensor) else None
            p = args[3] if len(args) > 3 else kwargs.get("p")
            p = self._scalar_of(p)
            if pos_table is not None and not isinstance(p, object) or pos_table is not None:
                p = self._require_position(node, p)
            return self.ops.embedding(ids, table, pos_table, p)
        if target == torchlib.rms_norm:
            return self.ops.rms_norm(self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1]), float(kwargs.get("eps", args[2] if len(args) > 2 else 1e-6)), name=str(node.name))
        if target == torchlib.rope:
            return self.ops.rope(self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1]), self._tensor_arg(node, args[2]), self._require_position(node, args[3]), layer=int(kwargs.get("layer", 0)), which=str(kwargs.get("which", "q")))
        if target == torchlib.swiglu:
            return self.ops.swiglu(self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1]), name=str(node.name))
        if target == torchlib.decode_attention:
            return self._lower_decode_attention(node, args, kwargs)

        # ---- plain functional torch ----------------------------------------
        if target in (torch.matmul, operator.matmul, torch.ops.aten.matmul.default if hasattr(torch.ops.aten, "matmul") else torch.matmul):
            return self._lower_matmul(node, args)
        if target in (torch.add, operator.add, torch.ops.aten.add.Tensor if hasattr(torch.ops.aten, "add") else torch.add):
            a, b = self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1])
            if a.value.shape != b.value.shape:
                raise _UnsupportedNode(node, f"broadcasting add {a.value.shape} + {b.value.shape}; the subset requires same-shape residuals")
            return self.ops.add(a, b, name=str(node.name))
        if target in (torch.mul, operator.mul):
            return self._lower_mul(node, args)
        if target in (torch.gelu, torch.nn.functional.gelu):
            return self.ops.gelu(self._tensor_arg(node, args[0]), name=str(node.name))
        if target == torch.nn.functional.layer_norm or target == torch.layer_norm:
            x = self._tensor_arg(node, args[0])
            g = self._tensor_arg(node, args[2])
            b = self._tensor_arg(node, args[3]) if len(args) > 3 and isinstance(args[3], SymbolicTensor) else None
            return self.ops.layer_norm(x, g, b, float(args[4] if len(args) > 4 else kwargs.get("eps", 1e-5)), name=str(node.name))
        if target == torch.nn.functional.embedding:
            ids = self._tensor_arg(node, args[0])
            w = self._tensor_arg(node, args[1])
            return self.ops.embedding(ids, w, None, self._position())
        if target in (torch.chunk, torch.split):
            return self._lower_chunk(node, args, kwargs)
        if target == operator.getitem:
            return self._lower_getitem(node, args)
        if target in (torch.flatten,):
            x = self._tensor_arg(node, args[0])
            start = int(args[1]) if len(args) > 1 else 1
            shape = x.value.shape[:start] + (-1,)
            shape = shape[:-1] + (x.value.numel // int(np_prod(x.value.shape[:start])),)
            return self.ops.view_of(x, str(node.name), shape)

        raise _UnsupportedNode(node, f"function {getattr(target, '__name__', target)!r} has no device-callable task lowering (§3.3)")

    def _lower_decode_attention(self, node, args, kwargs):
        q = self._tensor_arg(node, args[0])
        k_new = self._tensor_arg(node, args[1])
        v_new = self._tensor_arg(node, args[2])
        k_cache = self._tensor_arg(node, args[3])
        v_cache = self._tensor_arg(node, args[4])
        p = self._require_position(node, args[5])
        layer = int(kwargs.get("layer", 0))
        kvh = kwargs.get("kv_heads")
        kvh = int(kvh) if kvh is not None else None
        scale = kwargs.get("scale")
        scale = float(scale) if scale is not None else float(q.value.shape[-1] ** -0.5)
        k_post, v_post = self.ops.cache_append(k_cache, v_cache, k_new, v_new, p, layer=layer)
        scores = self.ops.attention_scores(q, k_post, p, scale=scale, layer=layer, kv_heads=kvh)
        probs = self.ops.softmax(scores, p, layer=layer)
        return self.ops.attention_values(probs, v_post, p, layer=layer, kv_heads=kvh)

    def _lower_matmul(self, node, args):
        x = self._tensor_arg(node, args[0])
        w = self._tensor_arg(node, args[1])
        if len(x.value.shape) != 2 or len(w.value.shape) != 2:
            raise _UnsupportedNode(node, f"matmul with ranks {len(x.value.shape)}x{len(w.value.shape)}; only 2D x 2D (linear) lowers")
        # x @ W with W stored [K, N] — the recorded convention.
        return self.ops.linear(x, w, None, name=str(node.name))

    def _lower_mul(self, node, args):
        # silu(g) * u  ->  swiglu(g, u)  (the Qwen3/Llama gate-up pattern).
        a, b = args[0], args[1]
        silu_input = None
        other = None
        for cand, rest in ((a, b), (b, a)):
            if isinstance(cand, SymbolicTensor):
                producer = self._producer_of(cand)
                if producer is not None and producer.op == "call_function" and _is_silu(producer.target):
                    silu_input = self.env.get(producer.args[0], producer.args[0])
                    other = rest
                    break
        if silu_input is not None and isinstance(silu_input, SymbolicTensor) and isinstance(other, SymbolicTensor):
            g = self._tensor_arg(node, silu_input)
            u = self._tensor_arg(node, other)
            if g.value.shape == u.value.shape:
                return self.ops.swiglu(g, u, name=str(node.name))
        raise _UnsupportedNode(node, "generic elementwise mul is outside the subset; swiglu(gate, up) (silu(g)*u) is the supported fused form")

    def _producer_of(self, sym: SymbolicTensor):
        for n in self.gm.graph.nodes:
            if self.env.get(n, None) is sym and n.op in ("call_function", "call_method", "call_module"):
                return n
        return None

    def _lower_chunk(self, node, args, kwargs):
        x = self._tensor_arg(node, args[0])
        dim = int(args[2] if node.target == torch.chunk and len(args) > 2 else kwargs.get("dim", 0))
        if node.target == torch.chunk:
            chunks = int(args[1])
            total = x.value.shape[dim]
            base = total // chunks
            rem = total % chunks
            lengths = [base + (1 if i < rem else 0) for i in range(chunks)]
        else:  # torch.split
            sizes = args[1]
            lengths = [int(s) for s in sizes]
        out, start = [], 0
        for i, length in enumerate(lengths):
            out.append(self.ops.narrow(x, f"{node.name}_{i}", axis=dim if dim >= 0 else dim + len(x.value.shape), start=start, length=length))
            start += length
        return out

    def _lower_getitem(self, node, args):
        base, index = args
        if isinstance(index, SymbolicTensor):
            # tensor[tensor] gather — an embedding lookup by token ids.
            return self.ops.embedding(index, self._tensor_arg(node, base), None, self._position())
        if isinstance(base, SymbolicTensor):
            spec = index if isinstance(index, tuple) else (index,)
            cur = base
            for ax, item in enumerate(spec):
                if isinstance(item, slice):
                    lo = item.start or 0
                    hi = item.stop if item.stop is not None else cur.value.shape[ax]
                    if item.step not in (None, 1):
                        raise _UnsupportedNode(node, "strided slices are outside the subset")
                    if (lo, hi) != (0, cur.value.shape[ax]):
                        cur = self.ops.narrow(cur, f"{node.name}_{ax}", axis=ax, start=int(lo), length=int(hi) - int(lo))
                elif isinstance(item, int):
                    cur = self.ops.narrow(cur, f"{node.name}_{ax}n", axis=ax, start=int(item), length=1)
                    shape = cur.value.shape[:ax] + cur.value.shape[ax + 1 :]
                    cur = self.ops.view_of(cur, f"{node.name}_{ax}s", shape)
                else:
                    raise _UnsupportedNode(node, f"index {item!r} unsupported")
            return cur
        raise _UnsupportedNode(node, f"getitem on {type(base).__name__} unsupported")

    # -- call_method: view-shaped tensor methods ---------------------------------

    _VIEW_METHODS = {"view", "reshape"}

    def _lower_call_method(self, node):
        torch = _torch()
        method = str(node.target)
        args = [self.env.get(a, a) for a in node.args]
        kwargs = {k: self.env.get(v, v) for k, v in node.kwargs.items()}
        base = self.env.get(node.args[0], node.args[0])
        if not isinstance(base, SymbolicTensor):
            raise _UnsupportedNode(node, f"method {method!r} on non-tensor")
        rest = args[1:]

        if method in self._VIEW_METHODS:
            shape = tuple(int(d) for d in (rest[0] if rest and not isinstance(rest[0], int) else rest))
            return self.ops.view_of(base, str(node.name), shape)
        if method == "contiguous":
            if not base.value.is_contiguous():
                raise _UnsupportedNode(node, "contiguous() on a non-contiguous view would copy; arrange views instead")
            return base
        if method in ("transpose", "t"):
            if method == "t":
                d0, d1 = -2, -1
            else:
                d0, d1 = int(rest[0]), int(rest[1])
            rank = len(base.value.shape)
            d0 = d0 % rank
            d1 = d1 % rank
            if (d0, d1) != (rank - 2, rank - 1):
                raise _UnsupportedNode(node, f"transpose({d0}, {d1}); only the last two dims lower (the tied-head pattern)")
            return self.ops.transpose_view(base, f"{base.value.name}.T")
        if method in ("chunk", "split"):
            return self._lower_chunk(node, [base] + rest, kwargs)
        if method == "narrow":
            dim, start, length = int(rest[0]), int(rest[1]), int(rest[2])
            return self.ops.narrow(base, str(node.name), axis=dim, start=start, length=length)
        if method in ("float", "half", "to", "long", "int"):
            raise _UnsupportedNode(node, f"dtype conversion {method!r} is outside the subset (weights/activations keep one dtype, §13.3)")
        if method in ("size", "dim", "numel", "shape"):
            # metadata query on a symbolic tensor: answer from the IR
            if method == "size":
                ax = int(rest[0]) if rest else None
                return base.value.shape[ax] if ax is not None else base.value.shape
            if method == "dim":
                return len(base.value.shape)
            return base.value.numel
        if method == "unsqueeze":
            raise _UnsupportedNode(node, "unsqueeze — reshape to the same layout instead")
        if method == "expand":
            raise _UnsupportedNode(node, "broadcasting expand is outside the subset")
        raise _UnsupportedNode(node, f"method {method!r} has no device-callable task lowering (§3.3)")

    # -- small utilities -----------------------------------------------------------

    def _tensor_arg(self, node, value) -> SymbolicTensor:
        if isinstance(value, SymbolicTensor):
            return value
        raise _UnsupportedNode(node, f"expected a tensor operand, got {value!r}")

    def _require_position(self, node, p):
        p = self._scalar_of(p)
        if p is None or not hasattr(p, "guard"):
            raise _UnsupportedNode(node, "this operator consumes the runtime position; declare a 'p' scalar (ops.define_scalar('p', 0, capacity))")
        return p


def np_prod(xs) -> int:
    n = 1
    for x in xs:
        n *= int(x)
    return n


def _is_silu(target) -> bool:
    torch = _torch()
    return target in (torch.nn.functional.silu, torch.silu) or getattr(target, "__name__", None) == "silu"


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def capture_torch_forward(
    module,
    *,
    example_inputs: Mapping[str, Any],
    scalars: Optional[Mapping[str, tuple[int, int]]] = None,
    backend: Optional[RecordingBackend] = None,
):
    """Trace ``module`` and lower its forward to the operator IR.

    ``example_inputs`` maps placeholder names to concrete tensors (these
    become the registered externals and default runtime bindings: ids, K/V
    cache views, any extra activations). ``scalars`` maps placeholder names
    to ``(lo, hi)`` guards — the decode position is conventionally
    ``{"p": (0, cache_capacity)}``. Returns ``(graph, recorder, outputs)``.
    """
    gm = _fx_trace(module)
    ops = backend if backend is not None else RecordingBackend()
    lowering = _GraphLowering(ops, gm, module, example_inputs, scalars or {})
    outputs = lowering.run()
    return ops.graph, ops, outputs


def compile_torch_forward(
    module,
    *,
    example_inputs: Mapping[str, Any],
    scalars: Optional[Mapping[str, tuple[int, int]]] = None,
    inputs: Sequence[str] = (),
    workers: int | None = None,
    kernel_name: str = "torch_megakernel",
):
    """Compile a traced torch module forward into one megakernel schedule.

    Thin wrapper: capture (:func:`capture_torch_forward`) + the generic
    :func:`~vkernels.compiler.compile.compile_forward` pipeline. The eager
    torch module doubles as the oracle for validation.
    """
    from .compile import compile_forward

    def build(ops: RecordingBackend):
        _, _, outputs = capture_torch_forward(module, example_inputs=example_inputs, scalars=scalars, backend=ops)
        return outputs

    return compile_forward(build, inputs=inputs, workers=workers, kernel_name=kernel_name)

"""Torch frontend: capture a ``torch.nn.Module`` forward into the operator IR.

This is the "given a model's forward pass" entry: the module's decode-step
forward is symbolically traced with :mod:`torch.fx`, and the traced graph
is lowered node-by-node onto the same §4.1 recording backend the GPT-2 /
Qwen3 frontends use. Capture stays model-agnostic — nothing here knows a
particular architecture.

Contract (§3.3, §4.2):

* The forward must be traceable: control flow may branch only on Python
  constants; branching on tensor values fails loudly at trace time.
* Nodes in the supported subset lower one-to-one onto recorded operators:

  - ``nn.Embedding`` / ``tensor[ids]`` / ``torchlib.embedding`` → embedding
  - ``nn.Linear`` / ``F.linear`` / ``x @ W`` / ``x @ W.T``       → linear
  - ``nn.LayerNorm`` / ``F.layer_norm``                          → layer_norm
  - ``torchlib.rms_norm``                                        → rms_norm
  - ``torchlib.rope``                                            → rope
  - ``torchlib.swiglu``, and the ``silu(g) * u`` pattern         → swiglu
  - ``+`` (same-shape residual)                                  → add
  - ``torch.gelu``                                               → gelu
  - ``torchlib.decode_attention`` (append + QK^T + softmax + PV) →
    cache_append, attention_scores, softmax, attention_values
  - view/reshape/flatten/squeeze/transpose/chunk/slice/select    → views

* Anything else is rejected with a §3.3 diagnostic naming the node and the
  missing contract — never silently run as an external kernel.

The same module runs eagerly with real tensors (``torchlib`` helpers are
plain torch functions), which gives an oracle that shares no code with the
compiled schedule: compare ``execute()`` against the eager forward.

This module imports torch lazily; the compiler package itself stays
torch-free at the IR level.
"""

from __future__ import annotations

import operator
from types import SimpleNamespace
from typing import Any, Mapping, Optional, Sequence

from .capture import CaptureError, RecordingBackend, SymbolicTensor

__all__ = ["torchlib", "capture_torch_forward", "compile_torch_forward"]


# ---------------------------------------------------------------------------
# torchlib: the decode-step helper library (module-level functions so
# torch.fx.wrap can mark them as leaf calls during tracing)
# ---------------------------------------------------------------------------


def _tl_embedding(ids, table, pos_table=None, p=None):
    out = table[ids.long()]
    if pos_table is not None:
        out = out + pos_table[p]
    return out


def _tl_rms_norm(x, gamma, eps=1e-6):
    import torch

    var = x.to(torch.float32).pow(2).mean(-1, keepdim=True)
    return (x * torch.rsqrt(var + eps) * gamma).to(x.dtype)


def _tl_rope(x, cos, sin, p):
    import torch

    half = x.shape[-1] // 2
    rotated = torch.cat((-x[..., half:], x[..., :half]), dim=-1)
    return x * cos[p] + rotated * sin[p]


def _tl_swiglu(gate, up):
    import torch

    return torch.nn.functional.silu(gate) * up


def _tl_decode_attention(q, k_new, v_new, k_cache, v_cache, p, *, layer=0, kv_heads=None, scale=None):
    """Append k/v at position ``p`` and attend over the valid prefix.

    ``k_cache``/``v_cache`` are per-layer views shaped [B, KVH, S, D]; they
    are mutated in place at [..., p, :] (eager path) / through the recorded
    cache_append effect (captured path). Returns ctx [B, H, D].
    """
    import math

    import torch

    B, H, D = q.shape
    kvh = kv_heads or H
    group = H // kvh
    scale = scale if scale is not None else 1.0 / math.sqrt(D)

    k_cache[..., p, :] = k_new
    v_cache[..., p, :] = v_new
    K = k_cache[..., : p + 1, :]  # [B, KVH, p+1, D]
    V = v_cache[..., : p + 1, :]

    kvh_of_h = torch.arange(H, device=q.device) // group  # q head -> kv head
    scores = torch.einsum("bhd,bhtd->bht", q.to(torch.float32), K[:, kvh_of_h].to(torch.float32)) * scale
    scores = scores - scores.max(dim=-1, keepdim=True).values
    probs = torch.exp(scores)
    probs = probs / probs.sum(dim=-1, keepdim=True)
    ctx = torch.einsum("bht,bhtd->bhd", probs, V[:, kvh_of_h].to(torch.float32))
    return ctx.to(q.dtype)


torchlib = SimpleNamespace(
    embedding=_tl_embedding,
    rms_norm=_tl_rms_norm,
    rope=_tl_rope,
    swiglu=_tl_swiglu,
    decode_attention=_tl_decode_attention,
)

_TORCHLIB_FNS = (
    _tl_embedding,
    _tl_rms_norm,
    _tl_rope,
    _tl_swiglu,
    _tl_decode_attention,
)


# ---------------------------------------------------------------------------
# FX interpretation -> recording backend
# ---------------------------------------------------------------------------


class _UnsupportedNode(CaptureError):
    def __init__(self, node, why: str):
        super().__init__(f"torch node {node!r} is outside the supported subset: {why}")


def _torch():
    import torch

    return torch


_wrapped = False


def _fx_trace(module):
    global _wrapped
    import torch.fx as fx

    if not _wrapped:
        # Mark the torchlib helpers as leaf calls so their eager bodies are
        # not traced; they lower whole at interpretation time.
        for fn in _TORCHLIB_FNS:
            try:
                fx.wrap(f"{__name__}.{fn.__name__}")
            except (RuntimeError, KeyError):  # already wrapped elsewhere
                pass
        _wrapped = True
    try:
        return fx.symbolic_trace(module)
    except Exception as exc:  # Proxy errors on data-dependent control flow etc.
        raise CaptureError(
            f"torch.fx could not trace the module ({type(exc).__name__}: {exc}); "
            "the forward must branch only on Python constants (§4.2)"
        ) from exc


def _prod(xs) -> int:
    n = 1
    for x in xs:
        n *= int(x)
    return n


def _attr_of(module, dotted: str):
    obj = module
    for part in dotted.split("."):
        obj = getattr(obj, part)
    return obj


class _GraphLowering:
    """Interprets an fx graph with symbolic values, recording operators."""

    def __init__(
        self,
        ops: RecordingBackend,
        gm,
        module,
        example_inputs: Mapping[str, Any],
        scalars: Mapping[str, tuple[int, int]],
    ):
        self.ops = ops
        self.gm = gm
        self.module = module
        self.example_inputs = dict(example_inputs)
        self.scalar_specs = dict(scalars)
        self.env: dict[Any, Any] = {}
        self.scalars: dict[str, Any] = {}  # placeholder name -> SymbolicScalar
        self._producer: dict[int, Any] = {}  # id(symbolic value) -> fx node

    # -- registration helpers -------------------------------------------------

    def _external(self, name: str, tensor) -> SymbolicTensor:
        return self.ops.register_external(name, tensor)

    def _track(self, node, value):
        self._producer[id(value)] = node
        return value

    def _position(self):
        # The canonical decode position, if the model declared one.
        return self.scalars.get("p")

    # -- node dispatch ---------------------------------------------------------

    def run(self) -> tuple[str, ...]:
        for node in self.gm.graph.nodes:
            if node.op == "placeholder":
                self.env[node] = self._lower_placeholder(node)
            elif node.op == "get_attr":
                self.env[node] = self._lower_get_attr(node)
            elif node.op == "call_function":
                self.env[node] = self._lower_call_function(node)
            elif node.op == "call_method":
                self.env[node] = self._lower_call_method(node)
            elif node.op == "call_module":
                self.env[node] = self._lower_call_module(node)
            elif node.op == "output":
                return self._lower_output(node)
        raise CaptureError("traced graph has no output node")

    def _lower_placeholder(self, node):
        name = str(node.target)
        if name in self.example_inputs:
            return self._external(name, self.example_inputs[name])
        if name in self.scalar_specs:
            lo, hi = self.scalar_specs[name]
            sc = self.ops.define_scalar(name, lo, hi)
            self.scalars[name] = sc
            return sc
        raise CaptureError(
            f"placeholder {name!r} is neither an example input nor a declared scalar; "
            "pass it via example_inputs/scalars so capture can bind it"
        )

    def _lower_get_attr(self, node):
        tensor = _attr_of(self.gm, str(node.target))
        if not hasattr(tensor, "shape"):
            raise _UnsupportedNode(node, f"attribute {node.target!r} is not a tensor (constants must enter as Python literals)")
        return self._external(str(node.target).replace(".", "_"), tensor)

    def _lower_output(self, node):
        val = self.env.get(node.args[0], node.args[0]) if node.args else None
        names = []
        vals = val if isinstance(val, (tuple, list)) else [val]
        for v in vals:
            if not isinstance(v, SymbolicTensor):
                raise _UnsupportedNode(node, f"output {v!r} is not a tensor; the compiled kernel's outputs must be tensor values")
            names.append(v.value.name)
        return tuple(names)

    # -- call_module: recognized parameterized layers ---------------------------

    def _lower_call_module(self, node):
        torch = _torch()
        mod = self._attr_of(self.module, str(node.target))
        args = [self.env.get(a, a) for a in node.args]

        if isinstance(mod, torch.nn.Linear):
            x = self._tensor_arg(node, args[0])
            w = self._external(f"{node.name}_weight", mod.weight)  # [out, in]
            wt = self.ops.transpose_view(w, f"{w.value.name}.T")  # [in, out]
            b = self._external(f"{node.name}_bias", mod.bias) if mod.bias is not None else None
            return self._track(node, self.ops.linear(x, wt, b, name=str(node.target).replace(".", "_")))
        if isinstance(mod, torch.nn.LayerNorm):
            x = self._tensor_arg(node, args[0])
            g = self._external(f"{node.name}_weight", mod.weight)
            b = self._external(f"{node.name}_bias", mod.bias) if mod.bias is not None else self._zero_bias(mod, node)
            return self._track(node, self.ops.layer_norm(x, g, b, mod.eps, name=str(node.target).replace(".", "_")))
        if isinstance(mod, torch.nn.Embedding):
            ids = self._tensor_arg(node, args[0])
            w = self._external(f"{node.name}_weight", mod.weight)
            return self._track(node, self.ops.embedding(ids, w, None, self._position()))
        raise _UnsupportedNode(node, f"module type {type(mod).__name__} has no megakernel lowering")

    def _zero_bias(self, mod, node):
        import numpy as np

        return self._external(f"{node.name}_zero_bias", np.zeros(tuple(mod.normalized_shape), dtype=np.float32))

    # -- call_function: functional ops + torchlib helpers ------------------------

    def _lower_call_function(self, node):
        torch = _torch()
        target = node.target
        args = [self.env.get(a, a) for a in node.args]
        kwargs = {k: self.env.get(v, v) for k, v in node.kwargs.items()}

        # ---- torchlib fused helpers (leaf calls, lowered whole) -----------
        if target == _tl_embedding:
            ids, table = self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1])
            pos_table = args[2] if len(args) > 2 and isinstance(args[2], SymbolicTensor) else None
            p = args[3] if len(args) > 3 else kwargs.get("p")
            p = self._scalar_of(p)
            if pos_table is not None:
                p = self._require_position(node, p)
            return self._track(node, self.ops.embedding(ids, table, pos_table, p))
        if target == _tl_rms_norm:
            eps = float(kwargs.get("eps", args[2] if len(args) > 2 else 1e-6))
            return self._track(node, self.ops.rms_norm(self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1]), eps, name=str(node.name)))
        if target == _tl_rope:
            return self._track(
                node,
                self.ops.rope(
                    self._tensor_arg(node, args[0]),
                    self._tensor_arg(node, args[1]),
                    self._tensor_arg(node, args[2]),
                    self._require_position(node, args[3]),
                    layer=int(kwargs.get("layer", 0)),
                    which=str(kwargs.get("which", "q")),
                ),
            )
        if target == _tl_swiglu:
            return self._track(node, self.ops.swiglu(self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1]), name=str(node.name)))
        if target == _tl_decode_attention:
            return self._lower_decode_attention(node, args, kwargs)

        # ---- plain functional torch ----------------------------------------
        if target in (torch.matmul, operator.matmul):
            return self._lower_matmul(node, args)
        if target in (torch.add, operator.add):
            a, b = self._tensor_arg(node, args[0]), self._tensor_arg(node, args[1])
            if a.value.shape != b.value.shape:
                raise _UnsupportedNode(node, f"broadcasting add {a.value.shape} + {b.value.shape}; the subset requires same-shape residuals")
            return self._track(node, self.ops.add(a, b, name=str(node.name)))
        if target in (torch.mul, operator.mul):
            return self._lower_mul(node, args)
        if target in (torch.gelu, torch.nn.functional.gelu):
            return self._track(node, self.ops.gelu(self._tensor_arg(node, args[0]), name=str(node.name)))
        if target in (torch.nn.functional.layer_norm, torch.layer_norm):
            x = self._tensor_arg(node, args[0])
            g = self._tensor_arg(node, args[2])
            b = self._tensor_arg(node, args[3]) if len(args) > 3 and isinstance(args[3], SymbolicTensor) else None
            eps = float(args[4] if len(args) > 4 else kwargs.get("eps", 1e-5))
            return self._track(node, self.ops.layer_norm(x, g, b, eps, name=str(node.name)))
        if target == torch.nn.functional.embedding:
            ids = self._tensor_arg(node, args[0])
            w = self._tensor_arg(node, args[1])
            return self._track(node, self.ops.embedding(ids, w, None, self._position()))
        if target in (torch.chunk, torch.split):
            return self._lower_chunk(node, [self.env.get(node.args[0], node.args[0])] + args[1:], kwargs)
        if target == operator.getitem:
            return self._lower_getitem(node, args)
        if target in (torch.flatten,):
            x = self._tensor_arg(node, args[0])
            start = int(args[1]) if len(args) > 1 else 1
            end = int(args[2]) if len(args) > 2 else len(x.value.shape)
            head, tail = x.value.shape[:start], x.value.shape[end:]
            mid = x.value.numel // max(_prod(head + tail), 1)
            return self._track(node, self.ops.view_of(x, str(node.name), tuple(head) + (mid,) + tuple(tail)))

        raise _UnsupportedNode(node, f"function {getattr(target, '__name__', target)!r} has no device-callable task lowering (§3.3)")

    def _lower_decode_attention(self, node, args, kwargs):
        q = self._tensor_arg(node, args[0])
        k_new = self._tensor_arg(node, args[1])
        v_new = self._tensor_arg(node, args[2])
        k_cache = self._tensor_arg(node, args[3])
        v_cache = self._tensor_arg(node, args[4])
        p = self._require_position(node, args[5])
        layer = int(kwargs.get("layer", 0))
        kvh = kwargs.get("kv_heads")
        kvh = int(kvh) if kvh is not None else None
        scale = kwargs.get("scale")
        scale = float(scale) if scale is not None else float(q.value.shape[-1] ** -0.5)
        k_post, v_post = self.ops.cache_append(k_cache, v_cache, k_new, v_new, p, layer=layer)
        scores = self.ops.attention_scores(q, k_post, p, scale=scale, layer=layer, kv_heads=kvh)
        probs = self.ops.softmax(scores, p, layer=layer)
        return self._track(node, self.ops.attention_values(probs, v_post, p, layer=layer, kv_heads=kvh))

    def _lower_matmul(self, node, args):
        x = self._tensor_arg(node, args[0])
        w = self._tensor_arg(node, args[1])
        if len(x.value.shape) != 2 or len(w.value.shape) != 2:
            raise _UnsupportedNode(node, f"matmul with ranks {len(x.value.shape)}x{len(w.value.shape)}; only 2D x 2D (linear) lowers")
        return self._track(node, self.ops.linear(x, w, None, name=str(node.name)))

    def _lower_mul(self, node, args):
        # silu(g) * u  ->  swiglu(g, u)  (the Llama/Qwen3 gate-up pattern).
        a, b = args[0], args[1]
        silu_input = None
        other = None
        for cand, rest in ((a, b), (b, a)):
            if isinstance(cand, SymbolicTensor):
                producer = self._producer.get(id(cand))
                if producer is not None and producer.op == "call_function" and _is_silu(producer.target):
                    silu_input = self.env.get(producer.args[0], producer.args[0])
                    other = rest
                    break
        if isinstance(silu_input, SymbolicTensor) and isinstance(other, SymbolicTensor):
            g = self._tensor_arg(node, silu_input)
            u = self._tensor_arg(node, other)
            if g.value.shape == u.value.shape:
                return self._track(node, self.ops.swiglu(g, u, name=str(node.name)))
        raise _UnsupportedNode(node, "generic elementwise mul is outside the subset; swiglu (silu(gate) * up) is the supported fused form")

    def _lower_chunk(self, node, args, kwargs):
        torch = _torch()
        x = self._tensor_arg(node, args[0])
        rank = len(x.value.shape)
        if node.target == torch.chunk:
            chunks = int(args[1])
            dim = int(args[2] if len(args) > 2 else kwargs.get("dim", 0))
            total = x.value.shape[dim]
            base, rem = divmod(total, chunks)
            lengths = [base + (1 if i < rem else 0) for i in range(chunks)]
        else:  # torch.split
            lengths = [int(s) for s in (args[1] if isinstance(args[1], (list, tuple)) else [args[1]])]
            dim = int(args[2] if len(args) > 2 else kwargs.get("dim", 0))
        dim = dim % rank
        out, start = [], 0
        for i, length in enumerate(lengths):
            out.append(self._track(node, self.ops.narrow(x, f"{node.name}_{i}", axis=dim, start=start, length=length)))
            start += length
        return out

    def _lower_getitem(self, node, args):
        base, index = args
        if isinstance(index, SymbolicTensor):
            # tensor[tensor] gather — an embedding lookup by token ids.
            return self._track(node, self.ops.embedding(index, self._tensor_arg(node, base), None, self._position()))
        if isinstance(base, SymbolicTensor):
            spec = index if isinstance(index, tuple) else (index,)
            cur = base
            for ax, item in enumerate(spec):
                if isinstance(item, slice):
                    lo = item.start if item.start is not None else 0
                    hi = item.stop if item.stop is not None else cur.value.shape[ax]
                    if item.step not in (None, 1):
                        raise _UnsupportedNode(node, "strided slices are outside the subset")
                    if int(lo) < 0 or int(hi) > cur.value.shape[ax]:
                        raise _UnsupportedNode(node, f"slice [{lo}:{hi}] out of bounds for axis {ax} of {cur.value.shape}")
                    if (lo, hi) != (0, cur.value.shape[ax]):
                        cur = self._track(node, self.ops.narrow(cur, f"{node.name}_{ax}", axis=ax, start=int(lo), length=int(hi) - int(lo)))
                elif isinstance(item, int):
                    if not (0 <= int(item) < cur.value.shape[ax]):
                        raise _UnsupportedNode(node, f"index {item} out of bounds for axis {ax}")
                    cur = self._track(node, self.ops.narrow(cur, f"{node.name}_{ax}n", axis=ax, start=int(item), length=1))
                    shape = cur.value.shape[:ax] + cur.value.shape[ax + 1 :]
                    cur = self._track(node, self.ops.view_of(cur, f"{node.name}_{ax}s", shape))
                else:
                    raise _UnsupportedNode(node, f"index {item!r} unsupported")
            return cur
        raise _UnsupportedNode(node, f"getitem on {type(base).__name__} unsupported")

    # -- call_method: view-shaped tensor methods ---------------------------------

    def _lower_call_method(self, node):
        method = str(node.target)
        args = [self.env.get(a, a) for a in node.args]
        base = self.env.get(node.args[0], node.args[0])
        if not isinstance(base, SymbolicTensor):
            raise _UnsupportedNode(node, f"method {method!r} on non-tensor")
        rest = args[1:]

        if method in ("view", "reshape"):
            raw = rest[0] if len(rest) == 1 and isinstance(rest[0], (list, tuple)) else rest
            shape = [int(d) for d in raw]
            if -1 in shape:
                known = _prod([d for d in shape if d != -1])
                if base.value.numel % known != 0:
                    raise _UnsupportedNode(node, f"view {shape} of {base.value.shape} is not layout-exact")
                shape = [d if d != -1 else base.value.numel // known for d in shape]
            return self._track(node, self.ops.view_of(base, str(node.name), tuple(shape)))
        if method == "contiguous":
            if not base.value.is_contiguous():
                raise _UnsupportedNode(node, "contiguous() on a non-contiguous view would copy; arrange views instead")
            return base
        if method in ("transpose", "t"):
            rank = len(base.value.shape)
            if method == "t":
                d0, d1 = rank - 2, rank - 1
            else:
                d0, d1 = int(rest[0]) % rank, int(rest[1]) % rank
            if (d0, d1) != (rank - 2, rank - 1):
                raise _UnsupportedNode(node, f"transpose({d0}, {d1}); only the last two dims lower (the tied-head pattern)")
            return self._track(node, self.ops.transpose_view(base, f"{base.value.name}.T"))
        if method in ("chunk", "split"):
            return self._lower_chunk(node, [base] + rest, {k: self.env.get(v, v) for k, v in node.kwargs.items()})
        if method == "narrow":
            dim, start, length = int(rest[0]), int(rest[1]), int(rest[2])
            return self._track(node, self.ops.narrow(base, str(node.name), axis=dim, start=start, length=length))
        if method in ("float", "half", "to", "long", "int", "bfloat16", "double"):
            raise _UnsupportedNode(node, f"dtype conversion {method!r} is outside the subset (weights/activations keep one dtype, §13.3)")
        if method in ("size", "dim", "numel", "shape"):
            if method == "size":
                ax = int(rest[0]) if rest else None
                return base.value.shape[ax] if ax is not None else base.value.shape
            if method == "dim":
                return len(base.value.shape)
            return base.value.numel
        if method == "unsqueeze":
            raise _UnsupportedNode(node, "unsqueeze — reshape to the same layout instead")
        if method == "expand":
            raise _UnsupportedNode(node, "broadcasting expand is outside the subset")
        raise _UnsupportedNode(node, f"method {method!r} has no device-callable task lowering (§3.3)")

    # -- small utilities -----------------------------------------------------------

    def _tensor_arg(self, node, value) -> SymbolicTensor:
        if isinstance(value, SymbolicTensor):
            return value
        raise _UnsupportedNode(node, f"expected a tensor operand, got {value!r}")

    def _scalar_of(self, p):
        return self.scalars[p] if isinstance(p, str) else p

    def _require_position(self, node, p):
        p = self._scalar_of(p)
        if p is None or not hasattr(p, "guard"):
            raise _UnsupportedNode(node, "this operator consumes the runtime position; declare a 'p' scalar (scalars={'p': (0, capacity)})")
        return p


def _is_silu(target) -> bool:
    torch = _torch()
    return target in (torch.nn.functional.silu, torch.silu) or getattr(target, "__name__", None) == "silu"


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def capture_torch_forward(
    module,
    *,
    example_inputs: Mapping[str, Any],
    scalars: Optional[Mapping[str, tuple[int, int]]] = None,
    backend: Optional[RecordingBackend] = None,
):
    """Trace ``module`` and lower its forward to the operator IR.

    ``example_inputs`` maps placeholder names to concrete tensors (these
    become the registered externals and default runtime bindings: ids, K/V
    cache views, any extra activations). ``scalars`` maps placeholder names
    to ``(lo, hi)`` guards — the decode position is conventionally
    ``{"p": (0, cache_capacity)}``. Returns ``(graph, recorder, outputs)``.
    """
    gm = _fx_trace(module)
    ops = backend if backend is not None else RecordingBackend()
    lowering = _GraphLowering(ops, gm, module, example_inputs, scalars or {})
    outputs = lowering.run()
    return ops.graph, ops, outputs


def compile_torch_forward(
    module,
    *,
    example_inputs: Mapping[str, Any],
    scalars: Optional[Mapping[str, tuple[int, int]]] = None,
    inputs: Sequence[str] = (),
    workers: int | None = None,
    kernel_name: str = "torch_megakernel",
):
    """Compile a traced torch module forward into one megakernel schedule.

    Thin wrapper: capture (:func:`capture_torch_forward`) + the generic
    :func:`~vkernels.compiler.compile.compile_forward` pipeline. The eager
    torch module doubles as the oracle for validation.
    """
    from .compile import compile_forward

    def build(ops: RecordingBackend):
        _, _, outputs = capture_torch_forward(module, example_inputs=example_inputs, scalars=scalars, backend=ops)
        return outputs

    return compile_forward(build, inputs=inputs, workers=workers, kernel_name=kernel_name)

