class _GraphLowering:
    """Interprets an fx graph with symbolic values, recording operators."""

    def __init__(
        self,
        ops: RecordingBackend,
        gm,
        module,
        example_inputs: Mapping[str, Any],
        scalars: Mapping[str, tuple[int, int]],
        *,
        scalar_env: Optional[dict] = None,
        submodule_cache: Optional[dict] = None,
    ):
        self.ops = ops
        self.gm = gm
        self.module = module
        self.example_inputs = dict(example_inputs)
        self.scalar_specs = dict(scalars)
        self.env: dict[Any, Any] = {}
        self.scalars: dict[str, Any] = scalar_env if scalar_env is not None else {}  # placeholder name -> SymbolicScalar (shared across nested lowerings)
        self._producer: dict[int, Any] = {}  # id(symbolic value) -> fx node
        self._submodule_cache = submodule_cache if submodule_cache is not None else {}

    # -- registration helpers -------------------------------------------------

    def _external(self, name: str, tensor) -> SymbolicTensor:
        return self.ops.register_external(name, tensor)

    def _track(self, node, value):
        self._producer[id(value)] = node
        return value

    def _position(self):
        # The canonical decode position, if the model declared one.
        return self.scalars.get("p")

    # -- node dispatch ---------------------------------------------------------

    def run(self, bindings: Optional[Mapping[str, Any]] = None):
        """Interpret the graph; returns the output value(s).

        ``bindings`` pre-binds placeholder names to symbolic values — used
        when lowering a nested submodule call: its parameters receive the
        caller's recorded arguments.
        """
        bindings = dict(bindings or {})
        for node in self.gm.graph.nodes:
            if node.op == "placeholder":
                name = str(node.target)
                if name in bindings:
                    self.env[node] = bindings[name]
                else:
                    self.env[node] = self._lower_placeholder(node)
            elif node.op == "get_attr":
                self.env[node] = self._lower_get_attr(node)
            elif node.op == "call_function":
                self.env[node] = self._lower_call_function(node)
            elif node.op == "call_method":
                self.env[node] = self._lower_call_method(node)
            elif node.op == "call_module":
                self.env[node] = self._lower_call_module(node)
            elif node.op == "output":
                return self.env.get(node.args[0], node.args[0]) if node.args else None
        raise CaptureError("traced graph has no output node")

