def _lower_call_module(self, node):
    torch = _torch()
    mod = self._attr_of(self.module, str(node.target))
    args = [self.env.get(a, a) for a in node.args]
    kwargs = {k: self.env.get(v, v) for k, v in node.kwargs.items()}

    if isinstance(mod, torch.nn.Linear):
