        wt = self.ops.transpose_view(w, f"{w.value.name}.T")  # [in, out]
        b = self._external(f"{node.name}_bias", mod.bias) if mod.bias is not None else None
        return self._track(node, self.ops.linear(x, wt, b, name=str(node.target).replace(".", "_")))
    if isinstance(mod, torch.nn.LayerNorm):
        x = self._tensor_arg(node, args[0])
        g = self._external(f"{node.name}_weight", mod.weight)
        b = self._external(f"{node.name}_bias", mod.bias) if mod.bias is not None else self._zero_bias(mod, node)
        return self._track(node, self.ops.layer_norm(x, g, b, mod.eps, name=str(node.target).replace(".", "_")))
    if isinstance(mod, torch.nn.Embedding):
        ids = self._tensor_arg(node, args[0])
        w = self._external(f"{node.name}_weight", mod.weight)
        return self._track(node, self.ops.embedding(ids, w, None, self._position()))

    # A user submodule: trace it too and lower its body with the caller's
    # recorded arguments bound to its parameters (nested interpretation).
    gm = self._submodule_cache.get(str(node.target))
    if gm is None:
        gm = _fx_trace(mod)
        self._submodule_cache[str(node.target)] = gm
    import inspect

    params = [p for p in inspect.signature(mod.forward).parameters if p != "self"]
    if len(params) < len(args):
        raise _UnsupportedNode(node, "more call arguments than submodule parameters")
    bindings = dict(zip(params, args))
    bindings.update(kwargs)
    sub = _GraphLowering(
        self.ops,
        gm,
        mod,
        {},
        {},
        scalar_env=self.scalars,
        submodule_cache=self._submodule_cache,
    )
    return sub.run(bindings)

