def _fns() -> dict:
    """Resolve possibly-moved torch function aliases once per process."""
    if not _FN_CACHE:
        t = _torch()

        def g(path):
            obj = t
            for part in path.split("."):
                obj = getattr(obj, part, None)
                if obj is None:
                    return None
            return obj

        _FN_CACHE.update(
            matmul=tuple(x for x in (g("matmul"), operator.matmul) if x is not None),
            add=tuple(x for x in (g("add"), operator.add) if x is not None),
            mul=tuple(x for x in (g("mul"), operator.mul) if x is not None),
            gelu=tuple(x for x in (g("nn.functional.gelu"), g("gelu")) if x is not None),
            layer_norm=tuple(x for x in (g("nn.functional.layer_norm"), g("layer_norm")) if x is not None),
            silu=tuple(x for x in (g("nn.functional.silu"), g("silu")) if x is not None),
            embedding=tuple(x for x in (g("nn.functional.embedding"),) if x is not None),
            chunk=tuple(x for x in (g("chunk"),) if x is not None),
            split=tuple(x for x in (g("split"),) if x is not None),
            flatten=tuple(x for x in (g("flatten"),) if x is not None),
        )
    return _FN_CACHE


