def _materialize(source: str) -> str:
    """Write the generated module to a real file (triton's @jit inspects
    source lines; exec'd strings are not allowed)."""
    import hashlib
    import os
    import tempfile

    tag = hashlib.sha256(source.encode()).hexdigest()[:16]
    cache_dir = os.path.join(tempfile.gettempdir(), "vkernels-megakernels")
    os.makedirs(cache_dir, exist_ok=True)
    path = os.path.join(cache_dir, f"mk_{tag}.py")
